const makeSection=(id,title,inner)=>{const s=document.createElement('section');s.className='card orbit-section closed';s.id=id;s.innerHTML=`<h2>${title}</h2><div class="orbit-content">${inner}</div>`;s.querySelector('h2').addEventListener('click',()=>s.classList.toggle('closed'));return s};
