 const settings=$(prefix+'Settings');settings.setAttribute('aria-pressed',String(qbEditMode));settings.classList.toggle('active',qbEditMode);
 list.querySelectorAll('[data-qb-edit]').forEach(b=>b.onclick=()=>{const x=db.entries.find(r=>r.id===b.dataset.qbEdit);if(!x)return;$(prefix+'Date').value=x.date;loadStageDate(prefix,kind);$(prefix+'Date').focus();msg(prefix+'Status','Entry loaded for '+displayDate(x.date)+'. Update the values and press Save Practice Entry.');});
