function safePct(a,b){return Number.isFinite(a)&&Number.isFinite(b)&&b>0?Math.max(0,Math.min(100,100*a/b)):null}
function testMetric(t,subject){const sd=t.subjects?.[subject]||{};const marks=safePct(num(sd.score),num(sd.max));const att=sd.attempted!==undefined&&sd.attempted!==null?num(sd.attempted):num(t.attempted),cor=sd.correct!==undefined&&sd.correct!==null?num(sd.correct):num(t.correct),total=sd.totalQuestions!==undefined&&sd.totalQuestions!==null?num(sd.totalQuestions):num(t.totalQuestions),acc=att>0?safePct(cor,att):null,rate=total>0?safePct(att,total):null;const m=[marks,acc,rate].filter(Number.isFinite);return m.length?m.reduce((a,b)=>a+b,0)/m.length:null}
function testConsistency(t,subject,prior){if(!prior.length)return 50;const v=testMetric(t,subject);if(!Number.isFinite(v))return 50;const valid=prior.map(x=>testMetric(x,subject)).filter(Number.isFinite);const avg=valid.reduce((n,x)=>n+x,0)/valid.length;return Number.isFinite(avg)?(v>=avg?100:Math.max(0,100*v/Math.max(avg,1))):50}
function testEfficiency(t,subject,prior){const sd=t.subjects?.[subject]||{},marks=safePct(num(sd.score),num(sd.max));const att=sd.attempted!==undefined&&sd.attempted!==null?num(sd.attempted):num(t.attempted),cor=sd.correct!==undefined&&sd.correct!==null?num(sd.correct):num(t.correct),total=sd.totalQuestions!==undefined&&sd.totalQuestions!==null?num(sd.totalQuestions):num(t.totalQuestions),acc=att>0?safePct(cor,att):null,rate=total>0?safePct(att,total):null;const parts=[marks,acc,rate].filter(Number.isFinite);if(!parts.length)return null;const base=parts.reduce((a,b)=>a+b,0)/parts.length;const cons=testConsistency(t,subject,prior);const delta=prior.length?(cons-50)/50*2:0;return Math.max(0,Math.min(100,base+delta))}
